import sys,json,re
from remote import root,sql
c=sys.argv[1];r=json.loads((root/(c+'-fixtures.json')).read_text());prefix=r['prefix'];assert re.fullmatch('SNAPLIST1485-(31|32)',prefix)
rows=sql(c,"SELECT JSON_OBJECT('kind','snapshot','id',s.id,'uuid',s.uuid,'name',s.name,'account',a.account_name,'accountId',s.account_id,'domain',d.uuid,'project',p.uuid,'volume',v.uuid,'created',DATE_FORMAT(s.created,'%Y-%m-%d %H:%i:%s'),'status',s.status,'type',s.snapshot_type,'description',s.type_description,'size',s.size) FROM snapshots s JOIN volumes v ON v.id=s.volume_id JOIN account a ON a.id=s.account_id JOIN domain d ON d.id=s.domain_id LEFT JOIN projects p ON p.project_account_id=s.account_id WHERE s.name LIKE '"+prefix+"%' AND s.removed IS NULL ORDER BY s.id; SELECT JSON_OBJECT('kind','reference','id',r.id,'snapshot',s.uuid,'role',r.store_role,'storeId',r.store_id,'path',r.install_path,'state',r.state,'size',r.size,'physical',r.physical_size) FROM snapshot_store_ref r JOIN snapshots s ON s.id=r.snapshot_id WHERE s.name LIKE '"+prefix+"%' AND r.state<>'Destroyed'; SELECT JSON_OBJECT('kind','volume','uuid',v.uuid,'path',v.path,'state',v.state,'name',v.name,'size',v.size) FROM volumes v WHERE v.name LIKE '"+prefix+"%' AND v.removed IS NULL;")
out={'snapshots':[x for x in rows if x['kind']=='snapshot'],'references':[x for x in rows if x['kind']=='reference'],'volumes':[x for x in rows if x['kind']=='volume']};assert len(out['snapshots'])==26 and len(out['volumes'])==3
(root/(c+'-db-before.json')).write_text(json.dumps(out,indent=2));print(c,'independent DB capture',len(out['snapshots']),'snapshots',len(out['references']),'refs')
